const BETA_TU_LESSONS=[{"id":"t_odlakani","g":"gt","t":"Odlákání","p":["<b>Odlákání</b> znamená, že soupeřovu figuru, která něco <b>hlídá</b>, donutíš odejít jinam. Hlídané pole nebo figura pak zůstane bez ochrany.","Nejsilnější je odlákání <b>šachem</b>: král nebo figura musí reagovat a na hlídání už nemá čas.","Než začneš hledat, zeptej se: <b>Kterou soupeřovu figuru hlídá jen jedna obránkyně?</b> Pak hledej, jak tu obránkyni odvést."],"ex":{"type":"seq","fen":"r4rk1/p2R4/2p3N1/8/8/P1n5/2P3PP/5RK1 b - - 0 33","last":"e5g6","task":"Bílá věž f1 je krytá jen králem. Odlákej krále.","steps":[{"task":"Dej šach, po kterém král nebude hlídat věž f1.","ok":["c3e2"],"okTxt":"Je2+! Král nemůže na f2 (hlídá ho tvoje věž), musí do rohu na h1.","hint":"Jezdec z c3 dá šach z pole e2.","reply":"g1h1","replyTxt":"Král musel na h1. Věž f1 je bez ochrany."},{"task":"Teď to dokonči.","ok":["f8f1"],"okTxt":"Vxf1 mat. Král na h1 nemá kam utéct.","hint":"Věž f8 bere věž f1."}],"endTxt":"Šach odvedl krále na h1 a věž f1 zůstala bez obrany. <b>Odlákání = obránce odvedeš pryč, pak bereš to, co hlídal.</b>"}},{"id":"t_vlakani","g":"gt","t":"Vlákání","p":["<b>Vlákání</b> je opak odlákání: soupeřovu figuru (nejčastěji krále) <b>nalákáš na špatné pole</b>, většinou obětí. Na tom poli ji pak dostaneš.","Typicky: obětuješ figuru na poli vedle krále, král ji musí sebrat – a tím vleze do matové sítě.","Oběť se vyplatí jen tehdy, když víš, co přijde po ní. Spočítej to dopředu až do konce."],"ex":{"type":"seq","fen":"r5rk/1b3p1p/p1q2Pp1/2p5/P2p3Q/B1P2R2/2P3PP/5RK1 w - - 2 26","last":"f8g8","task":"Černý král stojí na h8. Vlákej ho na h7 a dej mat.","steps":[{"task":"Obětuj dámu tak, aby ji král musel sebrat.","ok":["h4h7"],"okTxt":"Dxh7+! Král musí brát – jiný tah nemá.","hint":"Dáma bere pěšce h7 se šachem.","reply":"h8h7","replyTxt":"Král sebral dámu a stojí na h7."},{"task":"Král je na h7. Dej mat.","ok":["f3h3"],"okTxt":"Vh3 mat. Pěšec f6 a věž h3 nedají králi žádné pole.","hint":"Věž f3 jde na sloupec h."}],"endTxt":"Dáma vlákala krále na h7, kde ho věž zamatovala. <b>Vlákání = obětí přitáhneš krále tam, kde dostane mat.</b>"}},{"id":"t_mezitah","g":"gt","t":"Mezitah","p":["<b>Mezitah</b> je tah „mezi“: místo očekávaného tahu (třeba vzetí zpátky) nejdřív zahraješ něco silnějšího – nejčastěji <b>šach</b> nebo hrozbu, na kterou soupeř musí odpovědět.","Než automaticky bereš zpátky, zeptej se: <b>Nemám nejdřív šach nebo hrozbu, která mi pomůže?</b>"],"ex":{"type":"seq","fen":"r3kb1r/pp2pppp/2n2n2/8/3q4/5B2/PP3PPP/RNBQ1RK1 w kq - 0 10","last":"d8d4","task":"Černá dáma sebrala pěšce d4. Když ji vezmeš hned dámou, jezdec c6 vezme zpátky. Najdi mezitah.","steps":[{"task":"Nejdřív zahraj tah se šachem, který odstraní obránce d4.","ok":["f3c6"],"okTxt":"Sxc6+! Šach – černý musí brát a jezdec, který kryl d4, zmizel.","hint":"Střelec f3 bere jezdce c6 se šachem.","bad":{"d1d4":"Dxd4? Jxd4 – jezdec c6 kryje d4 a dámu ztratíš."},"reply":"b7c6","replyTxt":"Černý vzal střelce pěšcem."},{"task":"Teď vezmi dámu.","ok":["d1d4"],"okTxt":"Dxd4. Vyhrál jsi dámu za střelce.","hint":"Dáma d1 bere dámu d4."}],"endTxt":"Šach Sxc6+ byl mezitah: odstranil obránce d4 a soupeř musel odpovědět. Pak jsi bral bez rizika. <b>Mezitah = nejdřív šach nebo hrozba, pak teprve to, co soupeř čeká.</b>"}},{"id":"t_rentgen","g":"gt","t":"Rentgen","p":["<b>Rentgen</b> je útok <b>přes</b> jinou figuru. Dáma nebo věž míří na pole, i když je mezi nimi figura – jakmile figura zmizí (výměnou), linie se otevře.","Typicky: dvě tvoje těžké figury na stejné linii. Ta přední se vymění a ta zadní vstoupí do hry."],"ex":{"type":"seq","fen":"3Rr1k1/5ppp/p4q2/1pp1r3/8/1P2Q2P/P1P3P1/3R2K1 w - - 2 24","last":"e7e8","task":"Bílá věž d8 a dáma e3 míří na poslední řadu. Využij rentgen.","steps":[{"task":"Vezmi věž e8.","ok":["d8e8"],"okTxt":"Vxe8+! Černý musí brát zpátky věží e5.","hint":"Věž d8 bere na e8.","reply":"e5e8","replyTxt":"Věž z e5 vzala na e8 – a odešla ze sloupce e."},{"task":"Dáma teď vidí až na e8. Dokonči.","ok":["e3e8"],"okTxt":"Dxe8 mat. Dáma „prosvítila“ přes věž e5 – jakmile odešla, sloupec byl volný.","hint":"Dáma e3 bere na e8."}],"endTxt":"Dáma stála za věží e5 a čekala. Po výměně na e8 se sloupec otevřel. <b>Rentgen = útok přes figuru, která brzy zmizí.</b>"}},{"id":"t_preruseni","g":"gt","t":"Přerušení linie","p":["<b>Přerušení</b> (interference): postavíš figuru <b>mezi</b> soupeřovu figuru a to, co hlídá. Linie se přeruší a hlídaná figura zůstane bez ochrany.","Nejlépe to funguje se šachem nebo hrozbou – soupeř nemá čas přerušení vyřešit."],"ex":{"type":"seq","fen":"4rrk1/1p2q1pp/p2p4/3P4/1PPRnpB1/Q7/P5PP/2R3K1 w - - 1 29","last":"c7e7","task":"Černý jezdec e4 je krytý dámou e7. Přeruš sloupec e.","steps":[{"task":"Postav figuru se šachem mezi dámu e7 a jezdce e4.","ok":["g4e6"],"okTxt":"Se6+! Střelec přerušil sloupec e a dává šach. Dáma e7 už jezdce nekryje.","hint":"Střelec g4 jde na e6 se šachem.","reply":"g8h8","replyTxt":"Král utekl do rohu."},{"task":"Jezdec e4 je bez ochrany. Vezmi ho.","ok":["d4e4"],"okTxt":"Vxe4. Vyhrál jsi celého jezdce.","hint":"Věž d4 bere jezdce."}],"endTxt":"Střelec se postavil mezi dámu a jezdce a ještě dal šach. <b>Přerušení = figura mezi obránce a to, co hlídá.</b>"}},{"id":"t_uvolneni","g":"gt","t":"Uvolnění linie","p":["<b>Uvolnění</b> (clearance): tvoje vlastní figura stojí v cestě jiné tvojí figuře. Odklidíš ji – nejlépe <b>s tempem</b> (šachem nebo braním) – a linie se otevře.","Hledej: <b>Kterou linii by moje dáma nebo střelec potřebovali, a co jim stojí v cestě?</b>"],"ex":{"type":"seq","fen":"8/1q6/pP2k3/n2r1p2/5Bp1/P3P1Pp/5P1P/1Q1R2K1 b - - 1 33","last":"b3b1","task":"Černá dáma b7 by chtěla na g2, ale cestu blokuje tvoje věž d5. Uvolni diagonálu.","steps":[{"task":"Odklid věž z diagonály se šachem.","ok":["d5d1"],"okTxt":"Vxd1+! Věž zmizela z diagonály b7–g2 a ještě dává šach.","hint":"Věž d5 bere věž d1.","reply":"b1d1","replyTxt":"Bílá dáma vzala zpátky. Diagonála je volná."},{"task":"Dokonči.","ok":["b7g2"],"okTxt":"Dg2 mat. Dámu kryje pěšec h3.","hint":"Dáma b7 jde až na g2."}],"endTxt":"Věž odešla se šachem a dáma prošla. <b>Uvolnění = vlastní figura uhne z cesty, nejlépe se šachem.</b>"}},{"id":"t_tichy","g":"gt","t":"Tichý tah","p":["<b>Tichý tah</b> není šach ani braní, ale připraví neodvratnou hrozbu. Soupeř ho snadno přehlédne, protože „nic nebere“.","Když nevidíš žádný šach ani braní, zeptej se: <b>Jak přidat ještě jednu figuru do útoku?</b>"],"ex":{"type":"seq","fen":"3r1rk1/ppp1qpnp/5p2/4p3/4P1Q1/5R2/PPPN2PP/R6K w - - 4 16","last":"a8d8","task":"Dáma g4 míří na g7, ale jezdec g7 je krytý. Přidej do útoku další figuru.","steps":[{"task":"Najdi tichý tah, po kterém hrozí mat na g7.","ok":["f3g3"],"okTxt":"Vg3! Nic nebere, ale věž a dáma míří spolu na g7.","hint":"Věž f3 jde na sloupec g.","reply":"f6f5","replyTxt":"Černý zahrál f5 a napadá dámu. Pozdě."},{"task":"Dokonči.","ok":["g4g7"],"okTxt":"Dxg7 mat. Věž g3 kryje dámu.","hint":"Dáma bere na g7."}],"endTxt":"Vg3 nic nebralo, ale přidalo druhou figuru na g7. <b>Tichý tah = připravíš hrozbu, proti které už není obrana.</b>"}},{"id":"t_spiz2","g":"gt","t":"Špíz v praxi","p":["Připomeň si <b>špíz</b>: napadneš cennější figuru (nejčastěji krále šachem), ta uhne a odkryje figuru za sebou.","Hledej ho hlavně na <b>poslední řadě</b> a na otevřených liniích, kde stojí král a věž nebo dáma za sebou."],"ex":{"type":"seq","fen":"1r2k2r/5ppp/4p3/2np4/8/2P5/P4PPP/1R4K1 w k - 0 25","last":"a8b8","task":"Černý vzal tvou věž na b8. Za černým králem stojí věž h8. Využij to.","steps":[{"task":"Vezmi zpátky se šachem.","ok":["b1b8"],"okTxt":"Vxb8+! Šach na poslední řadě. Král musí z řady pryč.","hint":"Věž b1 bere na b8.","reply":"e8e7","replyTxt":"Král uhnul a odkryl věž h8."},{"task":"Teď ber.","ok":["b8h8"],"okTxt":"Vxh8. Špíz – za králem stála věž.","hint":"Věž b8 bere věž h8."}],"endTxt":"Šach na poslední řadě, král uhnul a za ním visela věž. <b>Špíz = král uhne, figura za ním padne.</b>"}},{"id":"t_zugzwang","g":"gt","t":"Nevýhoda tahu (zugzwang)","p":["<b>Zugzwang</b> je pozice, kdy by soupeř nejradši <b>netáhl</b> – každý jeho tah mu pozici zhorší. V šachu ale stát nejde.","Nejčastěji ho potkáš v pěšcových koncovkách: králové stojí proti sobě a kdo musí táhnout, musí jednomu poli uhnout."],"ex":{"type":"seq","fen":"8/8/5k2/3p3p/3P3P/5K2/8/8 w - - 5 54","last":"f5f6","task":"Pěšcová koncovka. Postav krále tak, aby černý musel ustoupit.","steps":[{"task":"Postav krále proti černému králi (opozice).","ok":["f3f4"],"okTxt":"Kf4! Králové stojí proti sobě a černý je na tahu. Musí ustoupit.","hint":"Král jde o pole dopředu proti černému králi.","reply":"f6e6","replyTxt":"Černý král musel uhnout."},{"task":"Cesta k pěšci h5 je volná.","ok":["f4g5"],"okTxt":"Kg5. Pěšec h5 padne a koncovka je vyhraná.","hint":"Král jde k pěšci h5."}],"endTxt":"Černý by nejradši zůstal stát, ale musel táhnout a pustit tvého krále dál. <b>Zugzwang = každý tah soupeře je špatný.</b>"}},{"id":"x_anastazie","g":"gx","t":"Mat Anastázie","p":["<b>Mat Anastázie</b>: jezdec zavře králi únikové pole a věž (nebo dáma) dá mat po krajním sloupci nebo řadě. Krále navíc blokují vlastní pěšci.","Hledej ho, když soupeřův král stojí na kraji a před ním jsou jeho pěšci."],"ex":{"last":"g2h3","type":"mate1","fen":"6k1/R6p/4N1p1/8/P6P/4n1PK/8/2r5 b - - 4 34","task":"Bílý král stojí na h3 za svými pěšci. Tvůj jezdec e3 hlídá g2 a g4. Dej mat.","okTxt":"Vh1 mat. Jezdec hlídá g2 i g4, pěšci g3 a h4 jsou králi v cestě.","hint":"Věž dá šach po sloupci h."}},{"id":"x_arabsky","g":"gx","t":"Arabský mat","p":["<b>Arabský mat</b>: věž dá mat králi v rohu a jezdec ji kryje a zároveň hlídá poslední pole. Je to jeden z nejstarších známých matů.","Klíčové postavení: jezdec <b>o pole šikmo</b> od rohu (f6 u krále na h8) a věž na sedmé řadě."],"ex":{"last":"e2e6","type":"mate1","fen":"7k/p5R1/1p2rN1p/3p4/P1nP4/5PK1/b5PP/8 w - - 0 39","task":"Černý král je v rohu h8. Jezdec f6 hlídá g8 a h7. Dej mat.","okTxt":"Mat! Věž dala šach těsně vedle krále a kryje ji jezdec f6, který hlídá i druhé pole. Funguje Vh7 i Vg8.","hint":"Věž jde na h7 vedle krále."}},{"id":"x_boden","g":"gx","t":"Bodenův mat","p":["<b>Bodenův mat</b>: dva střelci na <b>křížících se diagonálách</b> dají mat králi, kterého blokují vlastní figury. Typicky po dlouhé rošádě.","Pozor na něj, když máš dlouhou rošádu a soupeřovi střelci míří na b1 a a3."],"ex":{"last":"b2c3","type":"mate1","fen":"r3r1k1/5ppb/2pb3p/1p1p4/p2P2PP/P1P1B3/3N1P2/2KQ2RR b - - 0 23","task":"Bílý král je na c1. Tvůj střelec h7 hlídá diagonálu h7–b1. Dej mat druhým střelcem.","okTxt":"Sxa3 mat. Střelec a3 dává šach a hlídá b2, střelec h7 hlídá c2 a b1 a na d1 a d2 stojí bílé figury.","hint":"Střelec d6 bere pěšce a3."}},{"id":"x_naramenik","g":"gx","t":"Nárameníkový mat","p":["<b>Nárameníkový mat</b>: král stojí mezi dvěma vlastními figurami jako mezi <b>nárameníky</b> a nemůže do stran. Stačí jeden šach zepředu.","Často se stává po dlouhé rošádě, když jezdec zůstane na b1 a věž na d1."],"ex":{"last":"e1g3","type":"mate1","fen":"2r1k2r/2q1bpp1/p3p1p1/1p1pP1P1/7P/P3BPQ1/1PP5/1NKR3R b k - 0 21","task":"Bílý král c1 má po stranách jezdce b1 a věž d1. Dej mat.","okTxt":"Dxc2 mat. Král nemůže do stran – stojí tam jeho vlastní figury.","hint":"Dáma bere pěšce c2."}},{"id":"x_strelci","g":"gx","t":"Mat dvěma střelci","p":["<b>Dva střelci</b> vedle sebe mají obrovskou sílu: jeden hlídá světlá, druhý tmavá pole. Na otevřeném králi spolu snadno dají mat.","Typický obrázek: jeden střelec dá šach a druhý z dálky hlídá pole, kam by král utekl."],"ex":{"last":"g2f3","type":"mate1","fen":"5r1k/pp1Q2p1/2p4p/2bb4/8/5P2/PP5P/R2R3K b - - 0 25","task":"Bílý král je na h1. Střelec c5 hlídá g1. Dej mat druhým střelcem.","okTxt":"Sxf3 mat. Střelec f3 dává šach po diagonále, c5 hlídá g1.","hint":"Střelec d5 bere na f3."}},{"id":"x_operni","g":"gx","t":"Operní mat","p":["<b>Operní mat</b> se jmenuje podle partie, kterou Paul Morphy hrál v pařížské opeře (1858). Věž dá mat na poslední řadě a <b>střelec ji kryje</b> a hlídá únikové pole.","Typické postavení: věž na sloupci před králem a střelec na diagonále, který hlídá pole vedle krále."],"ex":{"last":"d7b5","type":"mate1","fen":"1r4k1/1r5R/1p2pBp1/pb1p2N1/6P1/2Pn4/N4P2/K7 w - - 2 33","task":"Černý král je na g8. Střelec f6 hlídá g7 a h8. Dej mat.","okTxt":"Vh8 mat. Věž kryje střelec f6, ten hlídá i g7, a pole f7 hlídá jezdec g5.","hint":"Věž h7 jde na h8."}},{"id":"x_pillsbury","g":"gx","t":"Mat věží a střelcem","p":["Věž a střelec jsou proti králi na poslední řadě silná dvojice: <b>věž dá šach</b> po řadě a <b>střelec hlídá únikové pole</b> (třeba g7).","Když soupeř šach zablokuje, vezmi blokující figuru – a je to mat."],"ex":{"type":"seq","fen":"6k1/p4p1p/1p2r2B/4pnP1/5p2/P1R5/5P1P/6K1 w - - 2 31","last":"d6f5","task":"Černý král je na g8. Střelec h6 hlídá g7. Dej mat na poslední řadě.","steps":[{"task":"Dej šach na poslední řadě.","ok":["c3c8"],"okTxt":"Vc8+! Černý může jen zablokovat věží.","hint":"Věž c3 jde na c8.","reply":"e6e8","replyTxt":"Černý se zakryl věží na e8."},{"task":"Dokonči.","ok":["c8e8"],"okTxt":"Vxe8 mat. Střelec h6 hlídá g7.","hint":"Věž bere na e8."}],"endTxt":"Šach na poslední řadě a střelec hlídal g7. <b>Věž dá šach, střelec zavře únik.</b>"}},{"id":"x_vlastovka","g":"gx","t":"Vlaštovčí ocas","p":["<b>Vlaštovčí ocas</b>: dáma dá mat <b>z pole hned vedle krále</b> šikmo, kryje ji jiná figura a dvě pole za králem mu blokují jeho vlastní figury nebo pěšci.","Tvar připomíná ocas vlaštovky: dvě pole za králem jsou obsazená a dáma stojí před ním."],"ex":{"last":"f1f2","type":"mate1","fen":"6k1/4qppp/2Q5/8/2P5/5P2/P2R1KPP/1r6 b - - 2 29","task":"Bílý král je na f2. Tvoje věž b1 hlídá první řadu. Dej mat dámou.","okTxt":"De1 mat. Dámu kryje věž b1 a král nemá kam.","hint":"Dáma jde na e1 vedle krále."}},{"id":"x_hak","g":"gx","t":"Hákový mat","p":["<b>Hákový mat</b>: věž dá mat a kryje ji jezdec, kterého zase kryje pěšec. Věž, jezdec a pěšec tvoří „hák“ kolem krále.","Hledej ho, když soupeřův král stojí uprostřed s pěšcem před sebou a tvůj jezdec je blízko."],"ex":{"last":"f2f3","type":"mate1","fen":"6R1/4kp2/4pN2/1p1pP3/1P1P4/5rPK/1r6/8 w - - 0 49","task":"Černý král je na e7. Jezdec f6 kryje pěšec e5. Dej mat věží.","okTxt":"Ve8 mat. Věž kryje jezdec, jezdce kryje pěšec e5.","hint":"Věž g8 jde na e8."}},{"id":"m_jezdec","g":"gm","t":"Silné pole pro jezdce","p":["<b>Silné pole</b> (předsunuté stanoviště) je pole na soupeřově polovině, odkud tvou figuru <b>žádný soupeřův pěšec nemůže vyhnat</b>. Nejlíp se na něj hodí jezdec.","Jezdec v centru na silném poli útočí na 8 polí a soupeř se ho zbaví jen výměnou za cennou figuru.","Postup: najdi pole, které soupeřovi pěšci už nikdy nenapadnou, odstraň figury, které ho hlídají, a postav tam jezdce."],"ex":{"type":"seq","fen":"r1bqkb1r/5p1p/p1np1p2/1p2p3/4P3/N1N5/PPP2PPP/R2QKB1R w KQkq - 0 10","task":"Sicilská obrana. Bílý právě vyměnil střelce za jezdce f6, který hlídal pole d5.","steps":[{"q":"Které pole je pro bílého jezdce teď nejlepší?","choices":["d5 – uprostřed, a černý pěšec ho už nemůže vyhnat","a4 – útočí na pěšce b5","e2 – v bezpečí doma"],"ans":0,"why":"Černé pěšce c a e už pole d5 nikdy nenapadnou (pěšec c zmizel, pěšec e stojí na e5). Jezdec tam bude jako skála.","no":{"1":"Jezdec na kraji šachovnice má málo polí a nic neovládá.","2":"Doma je jezdec bezpečný, ale nic nedělá."}},{"task":"Postav jezdce na silné pole.","ok":["c3d5"],"okTxt":"Jd5! Jezdec stojí uprostřed a nic ho odtud nevyžene.","hint":"Jezdec c3 jde na d5.","reply":"f8g7"},{"q":"Proč tě nemusí trápit, že černý může jezdce na d5 vyměnit za střelce?","choices":["Po výměně vezme pěšec e4 a pole d5 ovládneš znovu","Černý to nikdy neudělá","Jezdec je cennější než střelec"],"ans":0,"why":"Když černý dá figuru za jezdce, bílý vezme zpátky a pozice zůstane lepší. Černý by navíc přišel o figuru, která hlídá jeho slabá pole.","no":{"1":"Udělat to může – jen tím nic nezíská.","2":"Jezdec i střelec mají zhruba stejnou hodnotu, 3 pěšce."}}],"endTxt":"Jezdec na silném poli je často silnější než věž. <b>Hledej pole, ze kterého tě soupeřův pěšec nevyžene.</b>","last":"g7f6"}},{"id":"m_sedma","g":"gm","t":"Věž na sedmé řadě","p":["Věž na <b>sedmé řadě</b> (u černého na druhé) je jedna z nejsilnějších věcí ve střední hře i koncovce. Útočí na pěšce, kteří ještě nepostoupili, a drží soupeřova krále na poslední řadě.","Cesta na sedmou řadu vede přes <b>otevřený sloupec</b>. Než tam věž pošleš, zkontroluj vlastní poslední řadu – ať tě soupeřova věž nezamatuje."],"ex":{"type":"seq","fen":"2r3k1/pp3ppp/4p3/8/8/4P3/PP3PPP/3R2K1 w - - 0 1","task":"Máš otevřený sloupec d. Než věž půjde dopředu, zabezpeč krále.","steps":[{"q":"Proč nejdřív udělat králi okénko (posunout pěšce g nebo h)?","choices":["Aby tě černá věž nemohla zamatovat na první řadě","Aby pěšec útočil","Aby se král mohl hned vrátit do centra"],"ans":0,"why":"Když věž odejde z první řady, Vc1 by mohl být mat. Okénko tomu zabrání.","no":{"1":"Pěšec g3 nikam neútočí. Jde o bezpečí krále.","2":"Jde hlavně o to, aby tvůj král nedostal mat na první řadě."}},{"task":"Udělej králi okénko.","ok":["g2g3","g2g4","h2h3","h2h4"],"okTxt":"Král teď má kam utéct a věž může dopředu.","hint":"Posuň pěšce g nebo h o pole.","reply":"a7a5"},{"task":"Teď věž na sedmou řadu.","ok":["d1d7"],"okTxt":"Vd7! Věž útočí na pěšce b7 a f7 a drží černého krále na poslední řadě.","hint":"Věž jde po sloupci d až na d7.","reply":"c8b8"}],"endTxt":"Okénko, otevřený sloupec, sedmá řada. <b>Věž na sedmé řadě sbírá pěšce a svazuje krále.</b>"}},{"id":"m_strelec","g":"gm","t":"Dobrý a špatný střelec","p":["Střelec je <b>špatný</b>, když jeho vlastní pěšci stojí na polích jeho barvy. Pak mu blokují cestu a on jen kryje pěšce.","Střelec je <b>dobrý</b>, když jeho pěšci stojí na polích opačné barvy – diagonály má volné.","Proto: své pěšce dávej na pole opačné barvy, než má tvůj střelec. A špatného střelce se snaž vyměnit."],"ex":{"type":"seq","fen":"r2qkbnr/pp1b1ppp/2n1p3/2ppP3/3P4/2P2N2/PP3PPP/RNBQKB1R w KQkq - 3 6","task":"Francouzská obrana. Podívej se, na jakých polích stojí pěšci obou stran.","steps":[{"q":"Který černý střelec je špatný?","choices":["Střelec d7 – černí pěšci d5 a e6 stojí na světlých polích","Střelec f8","Oba jsou stejné"],"ans":0,"why":"Pěšci d5 a e6 stojí na světlých polích a zavírají světlopolnému střelci cestu.","no":{"1":"Střelec f8 je tmavopolný a pěšci na světlých polích mu nepřekáží.","2":"Pěšci stojí na světlých polích, takže to vadí jen světlopolnému střelci."}},{"q":"Co s takovým střelcem černý obvykle dělá?","choices":["Snaží se ho vyměnit nebo vyvést před pěšce (třeba přes b5 nebo a4)","Nechá ho stát doma","Obětuje ho"],"ans":0,"why":"Za řetězem pěšců nic neudělá. Výměnou se ho černý zbaví.","no":{"1":"Doma bude jen pasivně krýt pěšce.","2":"Obětovat figuru bez důvodu je ztráta."}},{"q":"A který bílý střelec je dobrý?","choices":["Světlopolný (f1) – bílí pěšci d4 a e5 stojí na tmavých polích","Tmavopolný (c1)","Žádný"],"ans":0,"why":"Bílí pěšci stojí na tmavých polích, takže světlopolný střelec má volné diagonály, třeba na h7.","no":{"1":"Tmavopolnému střelci pěšci d4 a e5 naopak překáží.","2":"Světlopolný bílý střelec je tady velmi dobrý."}}],"endTxt":"<b>Pěšci na polích barvy střelce = špatný střelec.</b> Stav pěšce na opačnou barvu nebo špatného střelce vyměň.","last":"c8d7"}},{"id":"m_izolovany","g":"gm","t":"Osamocený pěšec","p":["<b>Osamocený pěšec</b> nemá vedle sebe žádného vlastního pěšce, takže ho kryjí jen figury. Typicky je to pěšec d.","<b>Výhoda:</b> dává figurám prostor a pole uprostřed (e4, c4 nebo e5, c5). <b>Nevýhoda:</b> pole před ním je slabé a v koncovce se dá snadno sebrat.","Proti osamocenému pěšci: <b>zablokuj ho</b> (ideálně jezdcem přímo před ním), vyměň figury a útoč na něj."],"ex":{"type":"seq","fen":"r1bq1rk1/pp2bppp/2n2n2/2pp4/3P4/2N2NP1/PP2PPBP/R1BQ1RK1 w - - 5 9","task":"Tarraschova obrana. Černý má osamoceného pěšce d5. Hraješ za bílého proti němu.","steps":[{"q":"Které pole je pro bílého nejdůležitější?","choices":["d4 – pole přímo před osamoceným pěšcem","h4","a4"],"ans":0,"why":"Pole před osamoceným pěšcem nemůže napadnout žádný černý pěšec. Figura na d4 pěšce zastaví.","no":{"1":"Pole h4 s pěšcem d5 nesouvisí.","2":"Pole a4 s pěšcem d5 nesouvisí."}},{"task":"Zahraj tah, který jde proti osamocenému pěšci d5.","ok":["d4c5","c1g5","c1e3"],"okBy":{"d4c5":"dxc5! Pěšec d5 zůstal úplně sám a pole d4 před ním je tvoje. Tohle je nejsilnější tah.","c1g5":"Sg5 – napadá jezdce f6, který pěšce d5 kryje. Dobrý tah.","c1e3":"Se3 – střelec hlídá pole d4 před pěšcem. Dobrý tah."},"bad":{"g1h1":"Tah králem s pěšcem d5 nic nedělá."},"hint":"Nejsilnější je vzít pěšce c5: pěšec d5 pak zůstane úplně sám."}],"endTxt":"Proti osamocenému pěšci: <b>zablokuj pole před ním, vyměň figury a v koncovce ho seber.</b>","last":"e8g8"}},{"id":"m_mensinovy","g":"gm","t":"Menšinový útok","p":["<b>Menšinový útok</b>: útočíš <b>menším počtem pěšců</b> proti většímu. Typicky dva pěšci (a, b) proti třem (a, b, c).","Cíl není prorazit, ale <b>vytvořit soupeři slabého pěšce</b>. Po b4–b5 a výměně na c6 zůstane černému slabý pěšec c6 nebo osamocený pěšec d5.","Věž za pěšce (na b1) a tlačit b4–b5."],"ex":{"type":"seq","fen":"r1bqr1k1/pp2bppp/2p2nn1/3p2B1/3P4/2NBPN2/PPQ2PPP/1R3RK1 w - - 9 12","task":"Výměnná varianta Dámského gambitu. Věž stojí na b1. Spusť menšinový útok.","steps":[{"q":"Co je cílem menšinového útoku?","choices":["Vytvořit černému slabého pěšce na c6 nebo d5","Dát mat na dámském křídle","Proměnit pěšce b"],"ans":0,"why":"Po b5 a výměně na c6 zůstane černému slabý pěšec, na který budeš útočit figurami.","no":{"1":"Král je na druhé straně, o mat tu nejde.","2":"Pěšec b se po výměně na c6 obvykle vymění, nejde o proměnu."}},{"task":"Posuň pěšce b.","ok":["b2b4"],"okTxt":"b4! Další na řadě je b5.","hint":"Pěšec b2 jde o dvě pole.","reply":"a7a6"}],"endTxt":"<b>Menšinový útok = b4–b5 a slabý pěšec u soupeře.</b> Pak na něj míříš figurami.","last":"f8g6"}},{"id":"m_rosady","g":"gm","t":"Opačné rošády","p":["Když jsou králové <b>na opačných stranách</b> (jeden udělal krátkou, druhý dlouhou rošádu), rozhoduje <b>rychlost</b>.","Pěšce před soupeřovým králem můžeš klidně tlačit dopředu – tvůj král je daleko a pěšci ho nechrání. Kdo dřív otevře linie ke králi, vyhrává.","Ztracené tempo je tu dražší než pěšec."],"ex":{"type":"seq","fen":"r1bq1rk1/pp2ppbp/2np1np1/8/3NP3/2N1BP2/PPPQ2PP/2KR1B1R w - - 0 10","task":"Dračí varianta Sicilské. Bílý má dlouhou rošádu, černý krátkou.","steps":[{"q":"Co je teď pro bílého nejdůležitější?","choices":["Rychle zaútočit pěšci g a h na černého krále","Zabezpečit vlastního krále","Vyměnit dámy"],"ans":0,"why":"Pěšci g a h nechrání bílého krále, takže je bílý může poslat proti černému. Černý mezitím útočí na dámském křídle.","no":{"1":"Pomalá obrana nechá černého zaútočit jako prvního.","2":"Výměna dam útok ukončí. Bílý chce útočit."}},{"task":"Pošli pěšce do útoku.","ok":["g2g4","h2h4"],"okBy":{"g2g4":"g4! Pěšec jde na g5 a vyžene jezdce f6, který kryje krále.","h2h4":"h4! Pěšec jde na h5 a otevře sloupec h."},"alt":{"f1c4":"Sc4 je taky dobrý tah, ale teď si vyzkoušej pěšcový útok."},"hint":"Pěšec g nebo h jde o dvě pole.","reply":"c8d7"}],"endTxt":"Při opačných rošádách <b>útočí pěšci</b>. Kdo dřív otevře linie ke králi, vyhrává."}},{"id":"k_dama","g":"gk","t":"Mat dámou","p":["Mat dámou a králem musíš umět. Postup:","<b>1.</b> Dámou zavírej krále do čím dál menšího prostoru – tah jezdcem od něj (dáma stojí „o skok jezdce“ od krále).","<b>2.</b> Když je král zatlačený na kraji, přiveď svého krále.","<b>3.</b> Pozor na <b>pat</b>: když soupeř nemá žádný tah a není v šachu, je to remíza. Vždycky mu nech aspoň jedno pole, dokud nedáváš mat."],"ex":{"type":"play","fen":"8/8/8/4k3/8/8/8/3QK3 w - - 0 1","task":"Dej mat dámou a králem. Černý se brání nejlepšími tahy.","okTxt":"Mat! Dáma zatlačila krále na kraj a tvůj král jí pomohl.","hint":"Dámu postav o skok jezdce od černého krále – tak mu zavře nejvíc polí. Pak přiveď krále."}},{"id":"k_vez","g":"gk","t":"Mat věží","p":["Mat věží a králem trvá déle než dámou, ale postup je jednoduchý:","<b>1.</b> Věž odřízne krále po řadě nebo sloupci.","<b>2.</b> Tvůj král jde proti soupeřovu králi (opozice – králové stojí proti sobě).","<b>3.</b> Když stojí králové proti sobě, věž dá šach po řadě a zatlačí krále o řadu zpátky. Opakuj, až je král na kraji – pak je to mat.","Když soupeřův král útočí na věž, odtáhni ji daleko na druhou stranu."],"ex":{"type":"play","fen":"8/8/8/4k3/8/8/8/R3K3 w - - 0 1","task":"Dej mat věží a králem. Černý se brání nejlepšími tahy.","okTxt":"Mat! Věž dala šach na kraji a tvůj král hlídal pole před ní.","hint":"Věží odřízni krále, svého krále postav proti němu a pak dej šach věží. Věž drž daleko od černého krále."}},{"id":"k_vzdaleny","g":"gk","t":"Vzdálený volný pěšec","p":["<b>Vzdálený volný pěšec</b> je volný pěšec daleko od ostatních pěšců. V pěšcové koncovce je to obrovská výhoda.","Postup: <b>pošli ho dopředu</b>. Soupeřův král ho musí jít zastavit – a tím odejde od ostatních pěšců. Tvůj král pak sebere pěšce na druhé straně."],"ex":{"type":"play","fen":"8/8/4k3/7p/P6P/8/4K3/8 w - - 0 1","task":"Vyhraj koncovku: proměň pěšce. Černý se brání nejlepšími tahy.","okTxt":"Pěšec je v dámě. Pěšec a odlákal černého krále a tvůj král mezitím sebral pěšce h5.","hint":"Tlač pěšce a. Černý král musí za ním a tvůj král jde na pěšce h5."}},{"id":"k_nespravny","g":"gk","t":"Nesprávný střelec","p":["Krajní pěšec (a nebo h) a střelec <b>nevyhrají</b>, když střelec nehlídá roh, kde se pěšec proměňuje. Takovému střelci se říká <b>nesprávný</b>.","Pěšec h se proměňuje na h8 (tmavé pole). Světlopolný střelec ho neohlídá. Když se bránící král dostane do rohu h8, je to remíza – dostane nejvýš pat.","Jako obránce: <b>běž králem do rohu</b> a už z něj neodcházej."],"ex":{"type":"play","fen":"8/8/8/7P/4k3/8/4B3/1K6 b - - 0 1","task":"Hraješ za černého. Bílý má pěšce h a světlopolného střelce. Udrž remízu.","okTxt":"Král stojí v rohu h8 a světlopolný střelec ho odtud nevyžene.","hint":"Běž králem co nejrychleji do rohu h8 (přes f5, g6 nebo f6, g7).","goal":"draw","hold":12}}];
